import { Button } from "@heroui/react"
import { PlusIcon } from '@radix-ui/react-icons'
import React, { useState } from 'react'
import { useStateContext } from '../../contexts/ContextProvider'
import EntitiesFormModalAdmin from './EntitiesFormModalAdmin'


function AddEntity() {
  const [ismodalOpen, setisModalOpen] = useState(false);
  const [modalTitle, setmodalTitle] = useState("Add New Entity");
  const { currentColor } = useStateContext();
  const [updated, setUpdated] = useState(false);
  const [entity, setentity] = useState();

  const handleAddAction = () => {
    setisModalOpen(true);
    setmodalTitle("Add new entity");
  };
  return (
    <div className="w-full h-screen flex items-center justify-center">
      <Button
        style={{ background: currentColor }}
        onClick={handleAddAction}
        className="bg-transparent rounded text-white"
        endContent={<PlusIcon />}
        size="lg"
      >
        Add New
      </Button>
      {ismodalOpen && (
        <EntitiesFormModalAdmin
          ismodalOpen={ismodalOpen}
          setisModalOpen={setisModalOpen}
          entity={entity}
          modalTitle={modalTitle}
          updated={updated}
          setUpdated={setUpdated}
        />
      )}
    </div>
  );
}

export default AddEntity